import{_ as t,b as l,c as e,g as r}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"计算机视觉","description":"","frontmatter":{"title":"计算机视觉","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach/25.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach/25.md"}'),o={name:"articles/artificial-intelligence/books/AI-modern-approach/25.md"};function n(a,i,s,g,c,d){return l(),e("div",null,[...i[0]||(i[0]=[r('<p>第 25 章介绍计算机视觉的核心方法，从传统图像处理到深度学习视觉系统。重点包括：</p><h2 id="图像处理基础" tabindex="-1">图像处理基础</h2><ul><li><strong>卷积操作</strong>：平均核、Sobel 边缘检测（Gₓ、Gᵧ 梯度幅值和方向）</li><li><strong>特征检测</strong>：Harris 角点检测（自相关矩阵 M 的特征值分析）</li><li>卷积层参数计算、输出特征图尺寸、感受野</li></ul><h2 id="卷积神经网络-cnn" tabindex="-1">卷积神经网络（CNN）</h2><ul><li>卷积层、池化层、全连接层的堆叠</li><li><strong>ReLU</strong> 激活函数优于 Sigmoid 的原因</li><li><strong>批归一化（Batch Normalization）</strong>：加速训练、缓解内部协变量偏移</li><li>迁移学习与数据增强应对标注数据不足</li></ul><h2 id="目标检测" tabindex="-1">目标检测</h2><ul><li><strong>两阶段检测器</strong>（Faster R-CNN）：区域提议 + 分类</li><li><strong>单阶段检测器</strong>（YOLO）：网格预测边界框和类别概率</li><li><strong>非极大值抑制（NMS）</strong>：去除重叠检测框</li><li><strong>特征金字塔（FPN）</strong>：处理多尺度目标</li></ul><h2 id="分割任务" tabindex="-1">分割任务</h2><ul><li><strong>语义分割</strong>：像素级分类（所有同类物体同一标签）</li><li><strong>实例分割</strong>（Mask R-CNN）：区分同类不同实例</li><li>评价指标：IoU（交并比）、mAP（mean Average Precision）</li></ul><h2 id="实践应用" tabindex="-1">实践应用</h2><ul><li>图像分类（ImageNet）、行人检测（自动驾驶）</li><li>尺度不变性、恶劣天气下的领域自适应</li><li>离线测试集与真实道路部署的性能评估</li></ul>',11)])])}const h=t(o,[["render",n]]);export{p as __pageData,h as default};
